-- Contractor logo (shown at the top of the office screen), and polished logos for the demo companies.
alter table contractors add column if not exists logo_data text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'contractors_logo_size') then
    alter table contractors add constraint contractors_logo_size check (logo_data is null or (length(logo_data) < 400000 and logo_data like 'data:image/%'));
  end if;
end $$;

create or replace function set_contractor_logo(p_data text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare m profiles := me();
begin
  if m.contractor_id is null or not m.active or not m.is_org_admin then raise exception 'Only your company admin can change the logo.'; end if;
  if p_data is not null and (p_data not like 'data:image/png;base64,%' and p_data not like 'data:image/jpeg;base64,%' and p_data not like 'data:image/webp;base64,%' and p_data not like 'data:image/svg+xml;base64,%') then
    raise exception 'Use a PNG, JPG or SVG image.';
  end if;
  if length(coalesce(p_data, '')) >= 400000 then raise exception 'That image is too large. Use one under about 250 KB.'; end if;
  update contractors set logo_data = p_data where id = m.contractor_id;
  return jsonb_build_object('ok', true);
end $$;
revoke execute on function set_contractor_logo(text) from public, anon;
grant execute on function set_contractor_logo(text) to authenticated;

-- Demo logos (fictional companies)
update customers set logo_data = 'data:image/svg+xml;base64,' where name = 'Northside Grocers (demo)';
update customers set logo_data = 'data:image/svg+xml;base64,' where name = 'Red River Property Management (demo)';
update contractors set logo_data = 'data:image/svg+xml;base64,' where name = 'Arctic Air Mechanical (demo)';
